import java.sql.*;

public class StudentDemo {
    public static void main(String[] args) {

        String url  = "jdbc:mysql://localhost:3306/schooldb";
        String user = "root";
        String pass = "secret";

        // try-with-resources — শেষে নিজে থেকেই close হয়ে যায়
        try (Connection con = DriverManager.getConnection(url, user, pass);
             PreparedStatement ps =
                 con.prepareStatement("SELECT name, cgpa FROM STUDENT WHERE dept = ?")) {

            ps.setString(1, "CSE");              // ? এর জায়গায় মান বসানো

            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {              // এক এক করে row পড়া
                    System.out.println(rs.getString("name") + " - " + rs.getDouble("cgpa"));
                }
            }

        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
}

